# Lunar Konstruksi - Fase 7.4 Database-Synced Reference Match
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Phase([string]$Message) { Write-Host "[FASE 7.4] $Message" -ForegroundColor Cyan }
function Fail-Phase([string]$Message) { Write-Host ""; Write-Host "[FASE 7.4] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $parent = Split-Path -Parent $Path
  if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}
function Decode([string]$Value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail-Phase "Jalankan script dari repository Git Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot
$branch = (& git branch --show-current).Trim()
$head = (& git rev-parse --short HEAD).Trim()
Write-Phase "Repo   : $repoRoot"
Write-Phase "Branch : $branch"
Write-Phase "HEAD   : $head"

$trackedStatus = & git status --porcelain --untracked-files=no
if ($LASTEXITCODE -ne 0) { Fail-Phase "Tidak bisa membaca git status." }
if ($trackedStatus) {
  Write-Host "[FASE 7.4] Ada tracked changes. Installer tetap lanjut karena fase ini memang menimpa file desain tertentu." -ForegroundColor Yellow
  Write-Host $trackedStatus
}

$required = @(
  "components/site/home-page.tsx",
  "components/site/redesign/reference-home.tsx",
  "components/site/redesign/public-helpers.ts",
  "components/site/redesign/public-contact-form.tsx",
  "features/public-site/server.ts",
  "features/public-site/public-site.types.ts"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) { Write-Host "[FASE 7.4] Prasyarat yang belum ada:" -ForegroundColor Yellow; $missing | ForEach-Object { Write-Host "  - $_" }; Fail-Phase "Pastikan Fase 1-7.3 sudah terpasang." }

Write-Phase "Mengganti reference home dan media resolver agar memakai data CMS/Firestore asli..."
$backupDir = Join-Path $repoRoot ".lunar-backups/phase7_4"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Force -Path $backupDir | Out-Null }
foreach ($backupFile in @("components/site/redesign/reference-home.tsx", "components/site/redesign/public-helpers.ts")) {
  $source = Join-Path $repoRoot $backupFile
  if (Test-Path -LiteralPath $source) {
    $safeName = $backupFile.Replace("/", "__")
    Copy-Item -LiteralPath $source -Destination (Join-Path $backupDir $safeName) -Force
  }
}
Write-Host "[FASE 7.4] backup .lunar-backups/phase7_4" -ForegroundColor DarkGray
$payload = @{}
$payload["PHASE7_4_DATABASE_REFERENCE_SYNC.md"] = ""
$payload["components/site/redesign/public-helpers.ts"] = ""
$payload["components/site/redesign/reference-home.tsx"] = ""

foreach ($entry in $payload.GetEnumerator()) {
  $target = Join-Path $repoRoot $entry.Key
  Write-Utf8NoBom $target (Decode $entry.Value)
  Write-Host "[FASE 7.4] write  $($entry.Key)" -ForegroundColor DarkGray
}

Write-Host ""
Write-Host "[FASE 7.4] Selesai." -ForegroundColor Green
Write-Host "[FASE 7.4] Foto Team/Project/Service sekarang memprioritaskan media record database." -ForegroundColor Green
Write-Host "[FASE 7.4] Fallback foto eksternal dihapus; media kosong memakai placeholder teknis." -ForegroundColor Green
Write-Host ""
Write-Host "Validasi:" -ForegroundColor Cyan
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  git diff --check"
Write-Host "  git status --short"
